# Autotune over XBLOCK/YBLOCK; YBLOCK=1 configs keep y0 constant → coalesced stores
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 128, 'YBLOCK': 1}, num_warps=4, num_stages=1),
        triton.Config({'XBLOCK': 256, 'YBLOCK': 1}, num_warps=4, num_stages=2),
        triton.Config({'XBLOCK': 512, 'YBLOCK': 1}, num_warps=8, num_stages=2),
        triton.Config({'XBLOCK': 1024,'YBLOCK': 1}, num_warps=8, num_stages=2),
        triton.Config({'XBLOCK': 512, 'YBLOCK': 2}, num_warps=8, num_stages=3),
        # ... other configs with larger YBLOCK for comparison
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    # same store index — coalescing fixed by tile shape, not index arithmetic
    tl.store(out_ptr + (y0 + 3*x2 + 150528*y1), tmp0, mask)

def launch():
    grid = lambda META: (cdiv(xnumel, META['XBLOCK']), cdiv(ynumel, META['YBLOCK']))
    kernel[grid](in_ptr, out_ptr, ynumel, xnumel)
